    content: `
<h2 id="why">Зачем нужна специальная одежда</h2>
<p>Человек является основным источником загрязнения в чистом помещении. При обычной активности мы выделяем миллионы частиц в минуту: отмершие клетки кожи, волосы, волокна обычной одежды. Специальная одежда для чистых помещений создает барьер между оператором и контролируемой средой.</p>

<h2 id="types">Типы одежды по классам чистоты</h2>
<p>Комплект одежды определяется классом чистоты помещения:</p>
<ul>
  <li><strong>ISO 5 и выше (GMP A/B):</strong> полный комбинезон с капюшоном, стерильные перчатки, бахилы, маска, очки</li>
  <li><strong>ISO 6-7 (GMP C):</strong> комбинезон или халат с шапочкой, перчатки, бахилы</li>
  <li><strong>ISO 8 (GMP D):</strong> халат, шапочка, сменная обувь</li>
</ul>

<h2 id="materials">Материалы и ткани</h2>
<p>Для изготовления одежды используются синтетические ткани с минимальным ворсоотделением. Наиболее распространенные материалы: полиэстер с углеродной нитью для снятия статического заряда, Tyvek для одноразовых комплектов, а также специальные ламинированные ткани для стерильных зон.</p>

<h2 id="protocol">Протокол переодевания</h2>
<p>Правильная последовательность одевания и снятия спецодежды критически важна для поддержания чистоты. Переодевание производится в специальном шлюзе с разделением на «грязную» и «чистую» зоны. Каждый шаг должен быть задокументирован в СОП предприятия. Как правильно спроектировать сам шлюз — в разборе <a href="/blog/oshibki-proektirovaniya-gowning-room">10 ошибок проектирования gowning room</a>.</p>

<h2 id="care">Уход и стирка</h2>
<p>Многоразовая одежда для чистых помещений стирается в специализированных прачечных с контролем частиц. После стирки одежда упаковывается в чистой среде. Частота замены зависит от класса помещения: от каждой смены для ISO 5 до еженедельной для ISO 8.</p>
<p>В каталоге CRS представлены оба типа: <a href="/catalog/garments">одноразовая стерильная одежда</a> для зон ISO 5 (GMP A/B) и <a href="/catalog/reusable-garm">многоразовая одежда</a> для зон ISO 7–8 (GMP C/D). Для комплектации зоны переодевания также необходимы <a href="/catalog/cleanroom-shoes">обувь</a> и <a href="/catalog/cleanroom-sticky-mats">липкие коврики</a>.</p>
    `,
