    content: `
<h2 id="principle">Принцип работы</h2>
<p>HEPA (High Efficiency Particulate Air) и ULPA (Ultra Low Penetration Air) фильтры изготавливаются из стекловолоконной бумаги, сложенной в гофры для увеличения площади фильтрации. Частицы улавливаются за счет трех механизмов: инерционного столкновения, перехвата и диффузии.</p>

<h2 id="difference">HEPA vs ULPA</h2>
<p>Основное различие — в эффективности улавливания. Фильтры HEPA (H13-H14) задерживают 99,95-99,995% частиц размером 0,3 мкм. Фильтры ULPA (U15-U17) обеспечивают эффективность 99,9995-99,999995% для частиц 0,12 мкм. Выбор зависит от требуемого класса чистоты.</p>

<h2 id="selection">Выбор фильтра</h2>
<p>При выборе учитывайте: требуемый класс чистоты помещения, объем прокачиваемого воздуха, допустимое сопротивление воздушному потоку, габаритные размеры посадочного места. Для помещений ISO 5 и ниже рекомендуются фильтры класса H14, для ISO 7-8 достаточно H13.</p>

<h2 id="replacement">Замена и тестирование</h2>
<p>Срок службы HEPA-фильтра составляет от 3 до 5 лет. Критерий замены — увеличение перепада давления на фильтре до значения, указанного производителем. После установки нового фильтра обязательно проводится тест на целостность (DOP/PAO тест) для выявления утечек.</p>
    `,
