    content: `
<h2 id="purpose">Назначение передаточных окон</h2>
<p>Передаточные окна (pass-through, pass-box) предназначены для передачи материалов между зонами с разными классами чистоты без нарушения воздушного баланса. Они минимизируют контакт между зонами и снижают риск перекрестного загрязнения.</p>

<h2 id="types">Типы передаточных окон</h2>
<p>Статические передаточные окна — простейший вариант с механической блокировкой дверей (интерлок). Динамические передаточные окна оснащены HEPA-фильтром и системой продувки для дополнительной очистки передаваемых предметов. Существуют также модели с встроенным УФ-облучателем для обеззараживания поверхностей.</p>

<h2 id="airlocks">Воздушные шлюзы</h2>
<p>Воздушные шлюзы (air locks) используются для перемещения персонала и крупногабаритных грузов. Они оснащены системой блокировки дверей, подачей очищенного воздуха и, при необходимости, воздушным душем для удаления частиц с одежды.</p>

<h2 id="installation">Монтаж и эксплуатация</h2>
<p>Передаточное окно монтируется в стену между зонами с обеспечением герметичности стыков. Система интерлока не позволяет открыть обе двери одновременно. Регулярное обслуживание включает проверку уплотнений, работы блокировки и замену фильтров (для динамических моделей).</p>
    `,
